contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0, "precondition: non-empty targets");
        require(caddress != address(0), "precondition: non-zero callee");

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted || reverted);
    }

    receive() external payable {}
}

