contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        require(tos.length > 0);
        bool reverted;
        bool ret;
        (reverted, ret) = tryTransfer(from, target, tos, v);
        assert(!reverted && ret);
    }

